const out = [];

// Helper to extract HTML
function getHtmlFromItem(item) {
  if (typeof item.json.body === 'string' && item.json.body.trim()) return { html: item.json.body, source: 'json.body' };
  if (typeof item.json.data === 'string' && item.json.data.trim()) return { html: item.json.data, source: 'json.data' };

  if (item.binary && item.binary.data && item.binary.data.data) {
    try {
      const decoded = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
      if (decoded && /<html[^>]*>/i.test(decoded)) return { html: decoded, source: 'binary.data' };
    } catch {}
  }
  return { html: '', source: 'none' };
}

// 1. Grab the entire list of items from the config node once
const configItems = $('Attach Config & Timeout').all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const { html, source: htmlSource } = getHtmlFromItem(item);

  // --- 2. RESOLVE THE URL & CONFIG (MATCHING BY INDEX) ---
  let siteUrl = "";
  let config = {};

  // We look at the item in the config node that matches our current index i
  const sourceItem = configItems[i];

  if (sourceItem && sourceItem.json) {
    siteUrl = sourceItem.json.siteUrl || sourceItem.json["Website Link"];
    config = {
      timeoutMs: Number(sourceItem.json.timeoutMs || 5000),
      driveFolderId: sourceItem.json.driveFolderId,
      slackChannel: sourceItem.json.slackChannel,
      psiStrategy: sourceItem.json.psiStrategy || "mobile"
    };
  } else {
    siteUrl = "https://url-not-found-at-index-" + i + ".com";
  }

  // --- 3. THE "NO DATA" / SKELETON GUARD ---
  const isSkeleton = html.includes('<div id="root"></div>') && !html.includes('</h1>');

  if (!html || html.trim() === "" || isSkeleton) {
    out.push({
      json: {
        url: siteUrl,
        status: "No data available",
        seo: { title: "N/A", metaDesc: "N/A", robots: null, canonical: null, h1Count: 0 },
        summary: { 
          htmlSource, 
          error: isSkeleton ? "JavaScript-only Skeleton detected" : "Empty Response",
          internalLinksChecked: 0,
          brokenLinksCount: 0
        },
        brokenLinks: [],
        issues: [{ 
          level: "critical", 
          msg: isSkeleton ? "Site requires JavaScript rendering. No data extracted." : "No HTML content received." 
        }],
        critical: true,
        ...config
      }
    });
    continue;
  }

  // --- 4. FULL SEO ANALYSIS ---
  const issues = [];
  const warn = (msg) => issues.push({ level: "warning", msg });
  const crit = (msg) => issues.push({ level: "critical", msg });

  const grab = (re, s) => { const m = re.exec(s); return m ? m[1] : null; };
  const grabAll = (re, s) => {
    const arr = [];
    let m;
    while ((m = re.exec(s)) !== null) arr.push(m[1]);
    return arr;
  };

  const title = grab(/<title[^>]*>([\s\S]{0,2000}?)<\/title>/i, html)?.trim() || null;
  const metaDesc = grab(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']{0,4000})["'][^>]*>/i, html) ||
                   grab(/<meta[^>]*property=["']og:description["'][^>]*content=["']([^"']{0,4000})["'][^>]*>/i, html) || null;
  const robots = grab(/<meta[^>]*name=["']robots["'][^>]*content=["']([^"']+)["'][^>]*>/i, html);
  const h1s = grabAll(/<h1\b[^>]*>([\s\S]*?)<\/h1>/gi, html);
  const canonical = grab(/<link[^>]*rel=["']canonical["'][^>]*href=["']([^"']+)["'][^>]*>/i, html);

  if (!title) crit("Missing <title> tag.");
  if (!metaDesc) warn("Missing meta description.");
  if (h1s.length === 0) warn("Missing <h1>.");

  const imgTags = html.match(/<img\b[^>]*>/gi) || [];
  let imagesMissingAlt = 0;
  for (const img of imgTags) {
    if (!/alt\s*=\s*["'][^"']*["']/i.test(img)) imagesMissingAlt++;
  }
  if (imagesMissingAlt > 0) warn(`${imagesMissingAlt} image(s) without alt.`);

  // Link checking
  let host = null;
  try { host = new URL(siteUrl).host; } catch {}
  const linkRe = /<a\b[^>]*href=["']([^"']+)["'][^>]*>/gi;
  const linkHrefs = [];
  let mLink;
  while ((mLink = linkRe.exec(html)) !== null && linkHrefs.length < 30) {
    let href = mLink[1].trim();
    if (!href || /^javascript:|^mailto:|^tel:/i.test(href)) continue;
    try {
      const u = new URL(href, siteUrl);
      if (!host || u.host === host) linkHrefs.push(u.href);
    } catch {}
  }

  const uniqueLinks = [...new Set(linkHrefs)];
  const brokenLinks = [];

  async function checkUrl(url) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'HEAD', url, timeout: config.timeoutMs, resolveWithFullResponse: true, simple: false,
      });
      if ((res.statusCode || 0) >= 400) brokenLinks.push({ url, status: res.statusCode });
    } catch (e) {
      brokenLinks.push({ url, status: 'timeout/error' });
    }
  }

  for (const u of uniqueLinks) {
    await checkUrl.call(this, u);
  }

  out.push({
    json: {
      url: siteUrl,
      seo: { title, metaDesc, robots, canonical, h1Count: h1s.length },
      summary: {
        titlePresent: !!title,
        hasMetaDescription: !!metaDesc,
        h1Count: h1s.length,
        imagesMissingAlt,
        internalLinksChecked: uniqueLinks.length,
        brokenLinksCount: brokenLinks.length,
        htmlSource
      },
      brokenLinks,
      issues,
      critical: issues.some(i => i.level === "critical"),
      ...config
    }
  });
}

return out;

