// Node name: PSI (with backoff)
// Requires: env PSI_API_KEY (no default)
// Reads site URL from: item.json.url || item.json.summary?.url || item.json.siteUrl
// Outputs: item.json.psi = { ok, performance, rawError, testedUrl, fetchedAt, strategy }

const KEY = 'AIzaYOUR_GOOGLE_API_KEY_HERE';
if (!KEY) {
  // Fail fast so you don't waste retries without a key.
  throw new Error('PSI_API_KEY is not set. Add it to n8n environment and restart.');
}

const ENDPOINT = 'https://pagespeedonline.googleapis.com/pagespeedonline/v5/runPagespeed';

async function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

function extractError(e) {
  // Try to normalize different error shapes from n8n/http/got
  if (!e) return 'unknown_error';
  if (typeof e === 'string') return e;
  if (e?.message) return e.message;
  const res = e?.response;
  if (res) {
    const status = res.statusCode || res.status;
    let body = res.body || res.data;
    if (Buffer.isBuffer(body)) body = body.toString('utf8');
    let msg = '';
    try {
      const j = typeof body === 'string' ? JSON.parse(body) : body;
      msg = j?.error?.message || j?.message || '';
    } catch {
      // not JSON
      if (typeof body === 'string') msg = body.slice(0, 200);
    }
    return `HTTP ${status}${msg ? `: ${msg}` : ''}`;
  }
  return 'request_failed';
}

async function runPSI(url, strategy, quotaUser, attempts = 6) {
  let lastErr = null;
  for (let i = 0; i < attempts; i++) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET',
        url: ENDPOINT,
        qs: {
          url,
          strategy: strategy || 'mobile',
          category: 'performance',
          key: KEY,
          quotaUser: quotaUser || url, // helps distribute quota
        },
        json: true,
        // The helper ignores some libs' flags; we still guard with try/catch.
        // These hints help in newer n8n versions:
        resolveWithFullResponse: false,
        simple: false,
        throwHttpErrors: false,
        ignoreHttpStatusErrors: true,
      });

      // If PSI returned a valid JSON with lighthouseResult, we're done.
      if (res?.lighthouseResult?.categories?.performance?.score != null) {
        return res;
      }

      // If PSI returned JSON error shape, prepare to retry.
      if (res?.error?.message) {
        lastErr = new Error(res.error.message);
      } else if (typeof res === 'string' && /automated queries/i.test(res)) {
        // Google "Sorry" HTML
        lastErr = new Error('blocked_by_google_sorry_page');
      } else {
        // Unknown shape; stringify to inspect
        lastErr = new Error('psi_unknown_response');
      }
    } catch (e) {
      // Network or non-2xx thrown by transport
      const msg = extractError(e);
      lastErr = new Error(msg);
      // If it wasn't a 429-like situation, you can break early.
      if (!/429|rate|quota|limit|blocked/i.test(msg)) break;
    }

    // Backoff: 1s, 2s, 4s, 8s, 16s, 32s (+ jitter)
    const waitMs = (2 ** i) * 1000 + Math.floor(Math.random() * 400);
    await sleep(waitMs);
  }
  throw lastErr || new Error('psi_failed');
}

const out = [];
for (const item of items) {
  const siteUrl = item.json.url || item.json.summary?.url || item.json.siteUrl || 'https://example.com';
  const strategy = item.json.psiStrategy || 'mobile';

  const hostForQuota =
    (() => { try { return new URL(siteUrl).host; } catch { return siteUrl; } })();

  const psi = { ok: false, performance: null, rawError: null, testedUrl: null, fetchedAt: null, strategy: null };

  try {
    const raw = await runPSI.call(this, siteUrl, strategy, hostForQuota);
    const score = raw?.lighthouseResult?.categories?.performance?.score;
    psi.performance = (typeof score === 'number') ? Math.round(score * 100) : null;
    psi.ok = psi.performance !== null;
    psi.testedUrl = raw?.id || null;
    psi.fetchedAt = raw?.analysisUTCTimestamp || null;
    psi.strategy = raw?.lighthouseResult?.configSettings?.formFactor || strategy;
  } catch (e) {
    psi.rawError = extractError(e);
  }

  out.push({ json: { ...item.json, psi } });
}

return out;

const allItems = $input.all();
const mob = allItems[0]?.json || {};
const desk = allItems[1]?.json || {};

// Una categoría que PageSpeed no devolvió queda en null ("N/D"), nunca en 0/100.
const score = (data, key) => {
  const s = data?.lighthouseResult?.categories?.[key]?.score;
  return typeof s === 'number' ? Math.round(s * 100) : null;
};
const audit = (data, key) => data?.lighthouseResult?.audits?.[key]?.displayValue || 'N/A';

const mobileScore   = score(mob, 'performance');
const desktopScore  = score(desk, 'performance');
const mobileAccess  = score(mob, 'accessibility');
const desktopAccess = score(desk, 'accessibility');
const mobileBP      = score(mob, 'best-practices');
const desktopBP     = score(desk, 'best-practices');
const mobileSEO     = score(mob, 'seo');
const desktopSEO    = score(desk, 'seo');

const mobileFCP  = audit(mob, 'first-contentful-paint');
const desktopFCP = audit(desk, 'first-contentful-paint');
const mobileLCP  = audit(mob, 'largest-contentful-paint');
const desktopLCP = audit(desk, 'largest-contentful-paint');
const mobileTBT  = audit(mob, 'total-blocking-time');
const desktopTBT = audit(desk, 'total-blocking-time');
const mobileCLS  = audit(mob, 'cumulative-layout-shift');
const desktopCLS = audit(desk, 'cumulative-layout-shift');
const mobileSI   = audit(mob, 'speed-index');
const desktopSI  = audit(desk, 'speed-index');

const url   = 'https://sudogringo.github.io/FINAL/';
const fecha = new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' });
// Solo alerta un puntaje medido: un dato ausente no cuenta como 0.
const alerta = [mobileScore, desktopScore].some(s => s !== null && s < 80);
const estado = alerta ? 'ATENCION REQUERIDA' : 'OK';

const scoreColor = (s) => s >= 90 ? '#0cce6b' : s >= 50 ? '#ffa400' : '#ff4e42';
const scoreCell = (val) => val === null
  ? '<td style="text-align:center;color:#888">N/D</td>'
  : `<td style="text-align:center;color:${scoreColor(val)};font-weight:bold">${val}/100</td>`;
const textCell  = (val) => `<td style="text-align:center">${val}</td>`;
const row = (label, m, d, isScore, alt) => {
  const bg = alt ? 'background:#f7f7f7' : '';
  return `<tr style="${bg}"><td>${label}</td>${isScore ? scoreCell(m)+scoreCell(d) : textCell(m)+textCell(d)}</tr>`;
};

const htmlEmail = `<div style="font-family:Arial,sans-serif;max-width:680px;margin:0 auto">
<h2 style="color:#2d6a4f">Reporte SEO - Golden Harvest S.A.</h2>
<p><b>URL:</b> <a href="${url}">${url}</a></p>
<p><b>Fecha:</b> ${fecha} | <b>Estado:</b> ${estado}</p>
<table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse;width:100%;font-size:14px">
<tr style="background:#2d6a4f;color:white"><th style="text-align:left">Metrica</th><th>Mobile</th><th>Desktop</th></tr>
${row('Performance', mobileScore, desktopScore, true, false)}
${row('Accessibility', mobileAccess, desktopAccess, true, true)}
${row('Best Practices', mobileBP, desktopBP, true, false)}
${row('SEO', mobileSEO, desktopSEO, true, true)}
${row('First Contentful Paint', mobileFCP, desktopFCP, false, false)}
${row('Largest Contentful Paint', mobileLCP, desktopLCP, false, true)}
${row('Total Blocking Time', mobileTBT, desktopTBT, false, false)}
${row('Cumulative Layout Shift', mobileCLS, desktopCLS, false, true)}
${row('Speed Index', mobileSI, desktopSI, false, false)}
</table>
<p style="font-size:12px;color:#888;margin-top:16px">Generado automaticamente por n8n - Golden Harvest S.A.</p>
</div>`;

const shown = (s) => s ?? 'N/D';
const subjectAlerta = `ALERTA SEO Golden Harvest - Performance Mobile:${shown(mobileScore)} Desktop:${shown(desktopScore)}`;
const subjectOK     = `SEO OK - Golden Harvest (Mobile:${shown(mobileScore)} Desktop:${shown(desktopScore)})`;

return [{ json: {
  mobileScore, desktopScore, mobileAccess, desktopAccess,
  mobileBP, desktopBP, mobileSEO, desktopSEO,
  mobileFCP, desktopFCP, mobileLCP, desktopLCP,
  mobileTBT, desktopTBT, mobileCLS, desktopCLS, mobileSI, desktopSI,
  url, fecha, estado, alerta, htmlEmail, subjectAlerta, subjectOK
}}];
